<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, EditPen, Delete, Refresh } from '@element-plus/icons-vue'
import { knowledgeApi, subjectApi } from '@/api/modules'
import { isReported } from '@/api/http'
import type { KnowledgePoint, Subject } from '@/types'
const rows = ref<KnowledgePoint[]>([])
const subjects = ref<Subject[]>([])
const loading = ref(false)
const dialog = ref(false)
const editingId = ref<number | null>(null)
const filterSubject = ref<number | undefined>()
const form = reactive({ subjectId: undefined as number | undefined, parentId: undefined as number | undefined, name: '', description: '', sort: 1, status: 1 })
const subjectMap = computed(() => new Map(subjects.value.map((s) => [s.id, s.name])))
const parentOptions = computed(() => rows.value.filter((r) => r.subjectId === form.subjectId && r.id !== editingId.value))
async function load() { loading.value = true; try { const [s, k] = await Promise.all([subjectApi.list({ enabledOnly: false }), knowledgeApi.list({ subjectId: filterSubject.value, enabledOnly: false })]); subjects.value = s || []; rows.value = k || [] } finally { loading.value = false } }
function openCreate() { editingId.value = null; Object.assign(form, { subjectId: filterSubject.value || subjects.value[0]?.id, parentId: undefined, name: '', description: '', sort: 1, status: 1 }); dialog.value = true }
function openEdit(row: KnowledgePoint) { editingId.value = row.id; Object.assign(form, row); dialog.value = true }
async function save() { if (!form.subjectId || !form.name.trim()) return ElMessage.warning('请选择学科并填写知识点名称'); try { const payload = { ...form, parentId: form.parentId || null }; if (editingId.value) await knowledgeApi.update(editingId.value, payload); else await knowledgeApi.create(payload); ElMessage.success('知识点已保存'); dialog.value = false; await load() } catch (e) { if (!isReported(e)) ElMessage.error(e instanceof Error ? e.message : '保存失败') } }
async function remove(row: KnowledgePoint) { try { await ElMessageBox.confirm(`确定删除知识点“${row.name}”吗？请先确认没有题目或子知识点引用。`, '删除知识点', { type: 'warning' }); await knowledgeApi.remove(row.id); ElMessage.success('已删除'); await load() } catch { /* cancelled */ } }
onMounted(load)
</script>
<template><div class="page-content"><div class="page-title-row"><div><div class="eyebrow">KNOWLEDGE TAXONOMY</div><h1>知识点管理</h1><p>用多级知识树组织课程内容，支撑章节刷题与薄弱项统计。</p></div><div class="title-actions"><el-button :icon="Refresh" @click="load">刷新</el-button><el-button type="primary" :icon="Plus" @click="openCreate">新增知识点</el-button></div></div><section class="surface-card filter-card"><div class="filter-row"><el-select v-model="filterSubject" placeholder="全部学科" clearable @change="load"><el-option v-for="s in subjects" :key="s.id" :label="s.name" :value="s.id"/></el-select><span class="filter-help">知识点可以设置父级，实现多层级分类。</span></div></section><section class="surface-card data-card"><div class="table-toolbar"><div><h3>知识点列表</h3><p>{{ rows.length }} 个知识点</p></div></div><el-table :data="rows" v-loading="loading" stripe empty-text="暂无知识点"><el-table-column prop="id" label="ID" width="80"/><el-table-column prop="name" label="知识点名称" min-width="220"><template #default="scope"><div class="knowledge-name"><span class="knowledge-bullet"></span><strong>{{ scope.row.name }}</strong></div></template></el-table-column><el-table-column label="所属学科" min-width="180"><template #default="scope">{{ subjectMap.get(scope.row.subjectId) || `学科 #${scope.row.subjectId}` }}</template></el-table-column><el-table-column label="父级知识点" min-width="180"><template #default="scope">{{ rows.find(r => r.id === scope.row.parentId)?.name || '顶级知识点' }}</template></el-table-column><el-table-column prop="sort" label="排序" width="90"/><el-table-column label="状态" width="100"><template #default="scope"><el-tag :type="scope.row.status === 1 ? 'success' : 'info'">{{ scope.row.status === 1 ? '启用' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="scope"><el-button text type="primary" :icon="EditPen" @click="openEdit(scope.row)">编辑</el-button><el-button text type="danger" :icon="Delete" @click="remove(scope.row)">删除</el-button></template></el-table-column></el-table></section><el-dialog v-model="dialog" :title="editingId ? '编辑知识点' : '新增知识点'" width="560px"><el-form label-position="top"><el-form-item label="所属学科" required><el-select v-model="form.subjectId" @change="form.parentId = undefined"><el-option v-for="s in subjects" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="父级知识点"><el-select v-model="form.parentId" clearable placeholder="不选则创建顶级知识点"><el-option v-for="k in parentOptions" :key="k.id" :label="k.name" :value="k.id"/></el-select></el-form-item><el-form-item label="知识点名称" required><el-input v-model="form.name" maxlength="120"/></el-form-item><el-form-item label="描述"><el-input v-model="form.description" type="textarea" :rows="2"/></el-form-item><div class="form-two-cols"><el-form-item label="排序"><el-input-number v-model="form.sort" :min="0"/></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option label="启用" :value="1"/><el-option label="停用" :value="0"/></el-select></el-form-item></div></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
